// --- signed request helper (same wire format as convex/lib/hmac.ts) -------
// Re-signs on every attempt (fresh timestamp + nonce), because Convex rejects
// a reused nonce. Retries network errors, 408/429 and 5xx with backoff.
const crypto = require('crypto');
const secret = $env.N8N_TO_CONVEX_SECRET;
const baseUrl = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
if (!secret || !baseUrl) throw new Error('N8N_TO_CONVEX_SECRET and CONVEX_SITE_URL must be set in the n8n environment');

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const signedPost = async (path, data, attempts = 4) => {
  const body = JSON.stringify(data ?? {});
  let lastError;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    const timestamp = Math.floor(Date.now() / 1000).toString();
    const nonce = crypto.randomBytes(16).toString('hex');
    const signature = 'v1=' + crypto.createHmac('sha256', secret)
      .update(`${timestamp}.${nonce}.${body}`).digest('hex');
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: baseUrl + path,
        body,
        headers: {
          'Content-Type': 'application/json',
          'X-LendLoop-Timestamp': timestamp,
          'X-LendLoop-Nonce': nonce,
          'X-LendLoop-Signature': signature,
        },
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 15000,
      });
      const status = res.statusCode;
      const parsed = typeof res.body === 'string' ? JSON.parse(res.body || '{}') : res.body;
      if (status >= 200 && status < 300) return parsed;
      lastError = new Error(`Convex ${path} returned HTTP ${status}: ${JSON.stringify(parsed)}`);
      if (status < 500 && status !== 408 && status !== 429) break; // not retryable
    } catch (err) {
      lastError = err;
    }
    if (attempt < attempts) await sleep(1000 * 2 ** attempt);
  }
  throw lastError;
};
// --------------------------------------------------------------------------
// Ask Convex for overdue loans. Response contains only what a reminder needs.
const data = await signedPost('/n8n/overdue-loans', {});
return (data.loans || []).map((loan) => ({ json: loan }));

const loan = $('Fetch overdue loans (signed)').item.json;
const message = $json.error?.message || $json.error || 'Email delivery failed';
return {
  json: {
    loanId: loan.loanId,
    idempotencyKey: loan.idempotencyKey,
    status: 'failed',
    detail: String(message).slice(0, 300),
  },
};

