// --------------------------------------------------------------------------
// Idempotent write-back: the idempotencyKey (loan + day) comes from Convex,
// so re-running this node or the whole workflow never double-records.
const results = [];
for (const item of $input.all()) {
  const { loanId, idempotencyKey, status, detail } = item.json;
  const res = await signedPost('/n8n/reminder-status', { loanId, idempotencyKey, status, detail });
  results.push({ json: { loanId, status, duplicate: res.duplicate === true } });
}
return results;
